    explanation: '露点温度は、水蒸気量と気圧を変えずに空気を冷やしていったときに飽和に達し、凝結が始まる温度である。定義上、その空気の実際の水蒸気圧がちょうど飽和水蒸気圧と等しくなる温度なので、露点温度が高いほど含まれる水蒸気量が多いことを意味する。未飽和の空気では常に気温（乾球温度）より低く、両者が一致したときが相対湿度100 %である。気温と露点温度の差は湿数と呼ばれ、湿数が小さいほど湿っている。露点温度は気温が変化しても水蒸気の出入りがなければ変わらない保存性のよい指標だが、気圧が変わると飽和水蒸気圧との関係が変わるため厳密には気圧にも依存する。\n\n【図解】気温と露点温度の関係\n　状態｜気温と露点の関係｜湿数\n　未飽和｜気温＞露点｜正の値\n　飽和｜気温＝露点｜ゼロ\n　湿っている目安｜差が3 ℃以内｜雲や霧が出やすい\n　⇒ 露点温度が高いほど水蒸気量が多く、雲底も低くなる\n　⚠ 「露点温度が低いほど水蒸気が多い」は逆。また露点が気温を上回ることはない。',
