    explanation: '地上天気図の前線記号は、色と図形と配置で種類を区別する。寒冷前線は青色の三角、温暖前線は赤色の半円で表し、いずれも記号が付く側が前線の進行方向である。停滞前線は青い三角と赤い半円を前線の互いに反対側へ交互に描き、どちらへも進まないことを示す。閉塞前線は紫（赤紫）色で三角と半円を同じ側に交互に並べる。白黒の天気図では色が使えないため、図形の形と配置だけで判別することになる。記号の向きは進行方向を示す情報を持つので、ランダムに描かれることはない。\n\n【図解】前線記号の見分け方\n　前線｜色｜記号の配置\n　寒冷前線｜青｜三角が進行方向側\n　温暖前線｜赤｜半円が進行方向側\n　停滞前線｜青と赤｜三角と半円が反対側\n　閉塞前線｜紫｜三角と半円が同じ側\n　⇒ 記号が突き出している側が前線の進む向きを表す\n　⚠ 停滞前線と閉塞前線は、記号が反対側か同じ側かで区別する。取り違えが定番。',
