    subject: 'gakka1',
    subjectName: '予報業務に関する一般知識',
    question: '傾度風と地衡風の違いに関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '傾度風は気圧傾度力とコリオリ力のみのつり合いで定義される風である。', explanation: '誤り。気圧傾度力とコリオリ力のみのつり合いで定義されるのは地衡風である。傾度風はこれに加えて遠心力も考慮する。' },
      { key: 'B', text: '傾度風は摩擦力を考慮した風であり、地衡風は摩擦力を考慮しない風である。', explanation: '誤り。傾度風・地衡風はいずれも摩擦力を無視した自由大気中の風のモデルである。両者の違いは遠心力（等圧線の曲率効果）を考慮するかどうかにある。' },
      { key: 'C', text: '傾度風の風速は等圧線の曲率に関係なく、常に地衡風と等しい風速になる。', explanation: '誤り。傾度風は等圧線の曲率（低気圧性か高気圧性か）によって地衡風とは異なる風速になる。曲率が大きいほど地衡風との差が大きくなる。' },
      { key: 'D', text: '傾度風は気圧傾度力・コリオリ力に加えて遠心力も考慮した風で、低気圧性曲率の等圧線では地衡風より風速が弱く、高気圧性曲率の等圧線では地衡風より風速が強くなる。', explanation: '正しい。傾度風は曲線状の等圧線に沿う風として遠心力も含めてつり合いを考えるモデルであり、低気圧周りでは地衡風より弱く、高気圧周りでは地衡風より強くなる（傾度風バランス）。' },
    ],
    correctKey: 'D',
    explanation: '傾度風は等圧線が曲がっている場合に、気圧傾度力・コリオリ力・遠心力の三力がつり合って等圧線に沿って吹く風で、摩擦力は含まない。北半球の低気圧性曲率では風は反時計回りに回り、遠心力は中心から外向き、つまりコリオリ力と同じ向きに働く。したがって同じ気圧傾度力とつり合うのに必要なコリオリ力は小さくてすみ、風速は地衡風より弱くなる。逆に高気圧性曲率では遠心力が気圧傾度力と同じ向きになるため風速は地衡風より強い。この非対称性のため、高気圧では中心付近の気圧傾度が緩やかで、低気圧のような強い風になりにくい。\n\n【図解】曲率と風速の関係\n　曲率｜遠心力の向き｜地衡風との比較\n　低気圧性｜コリオリ力と同じ側｜弱い（亜地衡風）\n　高気圧性｜気圧傾度力と同じ側｜強い（超地衡風）\n　曲率なし｜遠心力ゼロ｜地衡風に一致\n　⇒ つり合う三力は気圧傾度力・コリオリ力・遠心力である\n　⚠ 摩擦力を含めるのは地上風の話。傾度風のつり合いに摩擦は入らない。',
