    choices: [
      { key: 'A', text: '環境減率が乾燥断熱減率より大きい（気温が高度とともに急激に下がる）場合、大気は絶対安定である。', explanation: '誤り。環境減率が乾燥断熱減率より大きい場合、未飽和・飽和のいずれの空気塊も周囲より常に暖かくなり浮力を持ち続けるため、絶対不安定と判定される。' },
      { key: 'B', text: '環境減率が湿潤断熱減率より小さい（気温の低下が緩やか）場合、大気は絶対不安定である。', explanation: '誤り。環境減率が湿潤断熱減率より小さい場合、飽和した空気塊でも周囲より冷たくなり浮力を失うため、絶対安定と判定される。' },
      { key: 'C', text: '大気の安定度は気圧のみによって判定され、気温減率は判定に関係しない。', explanation: '誤り。大気の安定度は環境の気温減率と、乾燥断熱減率・湿潤断熱減率との比較によって判定される。気圧そのものだけでは判定できない。' },
      { key: 'D', text: '環境減率が乾燥断熱減率より大きい場合は絶対不安定、湿潤断熱減率より小さい場合は絶対安定、その中間の場合は条件付き不安定と判定される。', explanation: '正しい。環境減率が乾燥断熱減率（約0.98℃/100m）を上回れば絶対不安定、湿潤断熱減率（状況により約0.5℃/100m前後）を下回れば絶対安定、両者の間にある場合は未飽和では安定・飽和すれば不安定になる「条件付き不安定」となる。' },
    ],
    correctKey: 'D',
    explanation: '大気の静的安定度は、実際の気温減率である環境減率Γeを、乾燥断熱減率Γd（約9.8 ℃/km）と湿潤断熱減率Γm（約4〜9 ℃/km）と比べて判定する。Γe＞Γd なら未飽和の空気塊でも持ち上げれば周囲より暖かくなり上昇を続けるので絶対不安定、Γe＜Γm なら飽和していても持ち上げた空気塊は周囲より冷たくなって戻るので絶対安定である。両者の間、Γm＜Γe＜Γd が条件付き不安定で、未飽和では安定だが飽和すると不安定になる。日本の暖候期はこの状態が多く、下層に暖湿気が入って強制上昇が加われば積乱雲が発達する。\n\n【図解】安定度の判定基準\n　環境減率の条件｜判定｜挙動\n　Γe＞Γd｜絶対不安定｜未飽和でも上昇継続\n　Γm＜Γe＜Γd｜条件付き不安定｜飽和すれば不安定\n　Γe＜Γm｜絶対安定｜飽和していても戻る\n　⇒ 気温減率だけでなく、空気が飽和しているかどうかで結論が変わる\n　⚠ 絶対安定と絶対不安定の不等号を入れ替える出題が定番。減率が大きい側が不安定。',
