    choices: [
      { key: 'A', text: 'CAPEはエマグラム上で自由対流高度（LFC）から平衡高度（EL）までの間、気塊の気温が周囲の気温より高い（気塊が正の浮力を持つ）領域の面積に相当し、値が大きいほど積乱雲が激しく発達する可能性を示す。', explanation: '正しい。CAPEはLFCからELまでの間で気塊が周囲より暖かく（浮力が正）保たれる領域をエマグラム上で積分した値で、大きいほど対流が激しく発達しうる潜在的なエネルギーが大きいことを示す。' },
      { key: 'B', text: 'CAPEは常に0 J/kg以上100 J/kg未満の小さな値をとる。', explanation: '誤り。CAPEは条件によって数百〜数千J/kg（強い大気不安定時には3000 J/kg以上）に達することもあり、範囲が固定されているわけではない。' },
      { key: 'C', text: 'CAPEが大きいほど大気は安定していることを示す。', explanation: '誤り。CAPEが大きいほど対流が発達した際に得られる浮力エネルギーが大きく、大気が不安定であることを示す。安定度が高いほどCAPEは小さくなる。' },
      { key: 'D', text: 'CAPEは気温減率とは無関係に、水蒸気量のみから計算される。', explanation: '誤り。CAPEは気塊の温度と環境（周囲）の気温の差を高度方向に積分して求める量であり、気温減率（環境の気温の高度変化）が本質的に関わる。水蒸気量だけで決まるものではない。' },
    ],
    correctKey: 'A',
    explanation: 'CAPE（対流有効位置エネルギー）は、自由対流高度 LFC から浮力がなくなる平衡高度 EL までの間で、上昇する空気塊の温度が周囲の気温より高い、すなわちエマグラム上で状態曲線が環境気温曲線より高温側にある領域の面積に対応する正の浮力エネルギーである。単位は J/kg で、大きいほど積乱雲が激しく発達しうることを示す。目安として1000 J/kg を超えると対流が起きやすく、2500 J/kg 以上では激しい対流の可能性が高いとされる。理論上の最大上昇流は約√(2×CAPE) で見積もられ、CAPE が2000 J/kg なら約63 m/sに相当する。気温減率と水蒸気量の両方が効く量である。\n\n【図解】CAPE の目安\n　CAPE｜対流の可能性｜最大上昇流のめやす\n　500 J/kg 未満｜弱い｜約30 m/s以下\n　1000〜2500 J/kg｜起きやすい｜約45〜70 m/s\n　2500 J/kg 以上｜激しい対流｜約70 m/s以上\n　⇒ CAPE はエマグラム上の正の浮力領域の面積として読み取れる\n　⚠ 「CAPE が大きいほど安定」は逆。また水蒸気量だけでなく気温減率にも依存する。',
