    explanation: 'K指数は、大気中下層の温度減率と湿りをまとめて評価する簡便な雷雨指数で、K＝(T850−T500)＋Td850−(T700−Td700) で計算される。第1項は850〜500 hPa の気温差で減率の大きさ、第2項は850 hPa の露点温度で下層の湿り、第3項は700 hPa の湿数（気温と露点の差）で中層の乾燥度合いを表し、中層が乾いているほど値が下がる。値が大きいほど中下層が湿って不安定であり、目安として20未満は雷雨の可能性が小さく、20〜30で可能性あり、30を超えると雷雨の可能性が高いとされる。中層が乾いている場合は過小評価になる点に注意する。\n\n【図解】K指数の構成\n　項｜内容｜大きいほど\n　T850−T500｜中下層の気温減率｜不安定\n　Td850｜下層の湿り｜湿潤\n　T700−Td700｜中層の湿数｜値を下げる\n　⇒ K指数はおおむね30を超えると雷雨の可能性が高いと判断する\n　⚠ 「値が小さいほど雷雨の可能性が高い」は逆。上層の風シアーは含まれない。',
