    explanation: '沈降性逆転層は、高気圧の中で空気がゆっくり沈降する際に断熱圧縮で昇温することによって上空にできる逆転層である。下降流は上層ほど強い傾向があるため、層の上部ほど昇温が大きくなり、その結果として上ほど暖かい安定層が形成される。高度は数百 mから数 kmの範囲にでき、その下では鉛直混合が抑えられるため大気汚染物質や水蒸気が滞留し、視程が悪化したり層雲や煙霧が広がったりする。夏の太平洋高気圧下では貿易風逆転層として持続し、対流の発達を抑えて雲頂高度を制限する。地表付近にできる接地逆転層とは成因も高度も異なる。\n\n【図解】沈降性逆転層の特徴\n　項目｜内容｜結果\n　成因｜高気圧内の下降流｜断熱圧縮で昇温\n　できる高さ｜数100 m〜数 km｜上空の安定層\n　下層への影響｜鉛直混合を抑制｜汚染物質の滞留\n　⇒ 対流の発達を頭打ちにし、雲頂高度を制限する\n　⚠ 放射冷却でできるのは接地逆転層。沈降性逆転層は下降流による断熱昇温が原因。',
