    subject: 'gakka1',
    subjectName: '予報業務に関する一般知識',
    question: '温帯低気圧の発達理論（傾圧不安定論）に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '温帯低気圧は台風と同様、暖かい海面からの水蒸気供給（潜熱）のみをエネルギー源として発達する。', explanation: '誤り。温帯低気圧の主要なエネルギー源は南北の温度差（有効位置エネルギー）であり、これを運動エネルギーに変換する傾圧不安定が発達の本質的な機構である。水蒸気の潜熱は補助的なエネルギー源となりうるが、台風のように潜熱のみに依存するわけではない。' },
      { key: 'B', text: '温帯低気圧は上層に寒気を伴わず、常に上層まで一様に暖かい構造を持つ。', explanation: '誤り。発達した温帯低気圧は典型的に上層に寒気（寒気core）を伴う構造を持ち、これが低気圧の発達に寄与する（上層トラフと地上低気圧の位相関係が重要）。' },
      { key: 'C', text: '温帯低気圧は前線帯（傾圧帯）の南北温度差をエネルギー源として、上層の正渦度移流と地上の低気圧性循環が結合しながら発達する。', explanation: '正しい。温帯低気圧の発達は前線帯（傾圧帯）における南北の温度差を主なエネルギー源とし、上層トラフ前面の正渦度移流による発散が地上の低気圧発達を支援し、地上と上層のシステムが結合（フィードバック）しながら急速に発達することがある（爆弾低気圧など）。' },
      { key: 'D', text: '温帯低気圧の発達には上層と地上のシステムの位相関係は無関係である。', explanation: '誤り。温帯低気圧の発達（傾圧不安定の成長）には、上層トラフと地上低気圧の位相のずれ（上層トラフが地上低気圧よりやや西に位置する関係など）が重要な役割を果たす。' },
    ],
    correctKey: 'C',
    explanation: '温帯低気圧は、前線帯の南北温度差がもつ有効位置エネルギーを運動エネルギーに変換する傾圧不安定によって発達する。台風のように潜熱だけを主エネルギー源とするのではなく、暖気の北上・上昇と寒気の南下・下降による熱輸送が本質である。構造的には上層に寒気を伴う寒気核型で、上層のトラフが地上低気圧の西側にやや傾いた位置関係にあることが発達の鍵となる。トラフ前面の正渦度移流が上層の発散を生み、下層からの上昇流を誘起して地上気圧を下げる。すると下層の暖気移流が強まり上層のトラフをさらに深めるという相互強化が働く。位相が鉛直に揃うと発達は止まり衰弱する。\n\n【図解】温帯低気圧の発達条件\n　要素｜内容｜働き\n　エネルギー源｜前線帯の南北温度差｜傾圧不安定\n　上層｜トラフ前面の正渦度移流｜発散と上昇流\n　位相関係｜上層トラフが地上低気圧の西側｜相互強化\n　構造｜寒気核型｜上層ほど中心が寒冷\n　⇒ 上層と下層の位相のずれがある間だけ低気圧は発達する\n　⚠ 「位相関係は無関係」は誤り。鉛直に位相が揃った時点で発達は終わる。',
