    correctKey: 'C',
    explanation: '閉塞前線の型は、寒冷前線の後面にある寒気と、温暖前線の前面にある寒気のどちらが冷たいかで決まる。後面の寒気のほうが冷たい場合は、その寒気が前面の寒気の下へもぐり込むので寒冷型閉塞前線となり、地上前線は寒冷前線的な性質を示す。逆に前面の寒気のほうが冷たい場合は、後面の相対的に暖かい空気が前面の寒気の上へ這い上がる形になり、温暖型閉塞前線となって温暖前線的な性質を示す。日本付近では海洋の影響で日本海側の寒気が変質しやすいなどの事情から、どちらの型が現れるかは事例により、上空の温度分布を確認して判断する必要がある。\n\n【図解】閉塞前線の型の判別\n　型｜後面の寒気｜前面の寒気\n　寒冷型｜より冷たい｜相対的に暖かい\n　温暖型｜相対的に暖かい｜より冷たい\n　地上での性質｜寒冷型は寒冷前線的｜温暖型は温暖前線的\n　⇒ 判別は前後の寒気の温度の相対関係であり、移動速度では決まらない\n　⚠ 前面と後面のどちらが冷たいかを入れ替える出題が定番。両者の関係を必ず確認する。',
