    correctKey: 'A',
    explanation: '500 hPa の等高度線と渦度分布を見ると、トラフ（気圧の谷）の軸付近で正渦度が極大となる。上層の風はおおむね西風なので、トラフの前面すなわち東側では正渦度が風下へ運ばれる正渦度移流の領域になる。準地衡風の考え方では、この正渦度移流の高度方向の増大が上層の発散をもたらし、質量を補うために下層から上昇流が誘起されて地上気圧が下がる。したがって地上低気圧はトラフ前面で発達しやすい。逆にトラフの後面（西側）は負渦度移流となり、上層の収束と下降流を伴って地上高気圧が強まりやすい。実技解析の基本的な着眼点である。\n\n【図解】上層トラフと地上の対応\n　位置｜渦度移流｜上層の場と地上\n　トラフ前面（東側）｜正渦度移流｜発散・上昇流で低気圧発達\n　トラフ軸付近｜正渦度の極大｜移流はほぼゼロ\n　トラフ後面（西側）｜負渦度移流｜収束・下降流で高気圧強化\n　⇒ 地上低気圧が上層トラフの前面に位置する間は発達が続く\n　⚠ 「トラフ後面で低気圧が発達」は誤り。発達を支えるのは前面の正渦度移流である。',
