    question: '台風の構造（眼・眼の壁雲・螺旋状降雨帯）に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '台風の眼の中では、風が非常に強く雨も最も激しい。', explanation: '誤り。台風の眼の中は下降流が卓越し、比較的風が弱く（凪に近いこともある）雲が少なく晴れることが多い。最も風が強く雨が激しいのは眼を取り巻く眼の壁雲（アイウォール）である。' },
      { key: 'B', text: '眼の壁雲（アイウォール）は台風の中で最も風が強く、対流活動が活発な領域であり、眼を取り囲むように発達した積乱雲群からなる。', explanation: '正しい。眼の壁雲（アイウォール）は台風の眼を取り囲むように発達した背の高い積乱雲群からなる領域で、台風の中で最も強い風と激しい降水を伴う、最も警戒すべき部分である。' },
      { key: 'C', text: '螺旋状降雨帯（スパイラルバンド）は台風の中心から離れた場所には形成されない。', explanation: '誤り。螺旋状降雨帯は台風の中心（眼）から外側へ渦を巻くように伸びる降水帯で、中心から離れた外側降雨帯（アウターバンド）としても形成され、中心から離れた地域でも強い雨や竜巻をもたらすことがある。' },
      { key: 'D', text: '台風の眼の直径は、台風の勢力（強さ）にかかわらず常に一定である。', explanation: '誤り。台風の眼の直径は台風ごと、また同じ台風でも発達段階によって変化し、数km〜100km程度まで幅がある。常に一定ではない。' },
    ],
    correctKey: 'B',
    explanation: '台風は中心から外へ向かって、眼・眼の壁雲・螺旋状降雨帯という同心円状の構造をもつ。眼は直径20〜200 km程度で、下降流のため雲が少なく風も弱く、気圧が最も低い。その外側を取り巻く眼の壁雲は幅数十 kmの積乱雲群で、最大風速と最も激しい降水がここに集中する。さらに外側には螺旋状降雨帯（スパイラルバンド）が中心から数百 kmにわたって伸び、断続的な強雨や突風、竜巻をもたらす。眼の直径は台風ごとに異なり、勢力が強く発達した台風ほど小さく明瞭になる傾向がある。眼の壁雲が二重になり内側が消える眼の壁雲交換も知られる。\n\n【図解】台風の同心円構造\n　部位｜位置｜特徴\n　眼｜中心（直径20〜200 km）｜下降流・弱風・少ない雲\n　眼の壁雲｜眼のすぐ外側｜最大風速と最強の降水\n　螺旋状降雨帯｜中心から数100 km｜断続的な強雨と突風\n　⇒ 最も危険なのは中心そのものではなく、眼を取り囲む壁雲である\n　⚠ 「眼の中で風雨が最も激しい」は誤り。眼は静穏で、通過時に一時的に晴れることもある。',
