    choices: [
      { key: 'A', text: '台風は温帯低気圧と同様、南北の温度差（傾圧性）を主なエネルギー源として発達する。', explanation: '誤り。南北の温度差（傾圧性）を主なエネルギー源とするのは温帯低気圧である。台風は傾圧性がほとんどない熱帯の一様に暖かい海域で、水蒸気の凝結に伴う潜熱を主なエネルギー源として発達する。' },
      { key: 'B', text: '台風は暖かい海面（一般に海面水温26〜27℃以上）から供給される水蒸気が凝結する際に放出する潜熱を主なエネルギー源として発達する。', explanation: '正しい。台風は熱帯の暖かい海面（目安として海面水温26〜27℃以上）から蒸発した大量の水蒸気が、台風内部で上昇・凝結する際に放出する凝結潜熱を主なエネルギー源として発達する暖気core構造の低気圧である。' },
      { key: 'C', text: '台風は上空の寒気の吹き込みのみをエネルギー源として発達する、寒気core型の低気圧である。', explanation: '誤り。台風は暖気core型の低気圧であり、上空の寒気の吹き込みをエネルギー源とするものではない（上空に寒気が入ると、むしろ台風から温帯低気圧への構造変化＝温帯低気圧化のきっかけとなることがある）。' },
      { key: 'D', text: '台風のエネルギー源は太陽放射の直接的な吸収であり、海面水温とは無関係である。', explanation: '誤り。台風のエネルギー源は海面からの水蒸気供給とその凝結潜熱であり、海面水温と密接に関係する。太陽放射を直接のエネルギー源とするものではない。' },
    ],
    correctKey: 'B',
    explanation: '台風は暖かい海面から蒸発した水蒸気が積乱雲の中で凝結する際に放出する潜熱を主エネルギー源とする、暖気核型（ウォームコア）の低気圧である。中心付近が周囲より暖かいため上空ほど中心の気圧が高くなり、上層では外向きの流出が生じる。発生・維持には海面水温がおおむね26〜27 ℃以上であることが必要で、上陸や冷たい海域への北上で水蒸気の供給が絶たれると急速に衰弱する。南北の温度差すなわち傾圧性をエネルギー源とする温帯低気圧とは発達機構が根本的に異なり、寒気の流入は台風にとってはむしろ衰弱や構造変化の要因になる。\n\n【図解】台風と温帯低気圧の比較\n　項目｜台風｜温帯低気圧\n　エネルギー源｜凝結潜熱｜南北の温度差\n　中心の構造｜暖気核｜寒気核\n　前線｜伴わない｜伴う\n　最強風の位置｜中心付近（壁雲）｜中心から離れた場所\n　⇒ 海面水温26〜27 ℃以上が台風の発生・維持のめやすである\n　⚠ 台風を寒気核型とするのは温帯低気圧との取り違え。台風は暖気核である。',
