    choices: [
      { key: 'A', text: '台風が温帯低気圧化すると、暖気core構造から前線を伴う非対称な構造（傾圧構造）に変化し、エネルギー源が潜熱主体から南北の温度差主体へ移行する。', explanation: '正しい。台風が中緯度に進み、周囲の水平温度傾度（傾圧帯）の影響を受けるようになると、対称的な暖気core構造から前線を伴う非対称な構造へ変化し、エネルギー源も海面からの潜熱主体から南北の温度差（傾圧性）主体へ移行する。この変化を温帯低気圧化という。' },
      { key: 'B', text: '台風が温帯低気圧化すると、必ず勢力（風速）が弱まり、災害をもたらす危険性はなくなる。', explanation: '誤り。温帯低気圧化した後も、広範囲で強風域が拡大したり、前線を伴うことで広い範囲に大雨をもたらしたりすることがあり、引き続き警戒が必要である。勢力が必ず弱まり危険性がなくなるわけではない。' },
      { key: 'C', text: '温帯低気圧化は、台風が赤道付近を通過する際に生じる現象である。', explanation: '誤り。温帯低気圧化は台風が中緯度（日本付近など、傾圧帯が存在する緯度帯）へ進んだ際に生じる現象であり、赤道付近で生じるものではない。' },
      { key: 'D', text: '温帯低気圧化した低気圧は、その後再び台風に戻ることが頻繁にある。', explanation: '誤り。温帯低気圧化は一般に不可逆的な構造変化であり、温帯低気圧化した後に再び台風（暖気core構造の熱帯低気圧）に戻ることは通常ない。' },
    ],
    correctKey: 'A',
    explanation: '台風の温帯低気圧化は、台風が中緯度へ北上して傾圧帯に入り、暖気核の対称構造から前線を伴う非対称な傾圧構造へ変わる過程である。エネルギー源も海面からの潜熱から南北の温度差へ移行する。この際、暖気側と寒気側の風速差により強風域はむしろ北側や東側に広がることがあり、風速が中心付近で弱まっても暴風域が拡大したり、前線に伴う大雨域が離れた場所に生じたりするため警戒が必要である。温帯低気圧化した後に再発達することもある。なお温帯低気圧化は中緯度で起こる現象であり、赤道付近で生じるものではなく、温帯低気圧が再び台風に戻ることも通常はない。\n\n【図解】温帯低気圧化に伴う変化\n　項目｜台風のとき｜温帯低気圧化後\n　構造｜暖気核で同心円状｜傾圧構造で非対称\n　エネルギー源｜凝結潜熱｜南北の温度差\n　前線｜伴わない｜伴う\n　強風域｜中心付近に集中｜広い範囲に拡大\n　⇒ 中心の風が弱まっても強風域が広がるため危険は続く\n　⚠ 「温帯低気圧化すれば危険はなくなる」は誤り。むしろ影響範囲は広がることがある。',
