    question: '地球の放射収支（入射・反射・射出のバランス）に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '地球全体で長期的に見ると、大気上端で入射する太陽放射（吸収分）と地球から宇宙空間へ射出される赤外放射（地球放射）は、ほぼ釣り合っている。', explanation: '正しい。地球全体・長期間で平均すると、大気上端で吸収される太陽放射エネルギーと、地球（大気＋地表）から宇宙空間へ射出される赤外放射エネルギーはほぼ釣り合っており、これにより地球全体の平均気温がほぼ一定に保たれる（放射平衡）。' },
      { key: 'B', text: '地球が受け取る太陽放射のうち、反射される割合（アルベド）は0（まったく反射しない）である。', explanation: '誤り。地球のアルベド（反射率）は雲・氷雪・地表面などにより約30 %程度と見積もられており、0ではない。' },
      { key: 'C', text: '低緯度では入射する太陽放射（吸収分）が射出される赤外放射より少なく、放射収支は負（赤字）である。', explanation: '誤り。低緯度（熱帯付近）では太陽放射の入射（吸収）が赤外放射の射出を上回り、放射収支は正（黒字）である。放射収支が負（赤字）になるのは高緯度側である。' },
      { key: 'D', text: '高緯度では放射収支が正（黒字）であり、大気・海洋による熱輸送は不要である。', explanation: '誤り。高緯度では射出される赤外放射が入射する太陽放射（吸収分）を上回り、放射収支は負（赤字）である。この低緯度と高緯度の放射収支の不均衡を解消するために、大気・海洋による低緯度から高緯度への熱輸送が生じる。' },
    ],
    correctKey: 'A',
    explanation: '地球全体を長期平均で見ると、大気上端で吸収される太陽放射と宇宙へ射出される赤外放射がほぼ釣り合っており、これを放射平衡という。入射する太陽放射のうち約30 %は雲・大気・地表で反射され（地球全体のアルベドは約0.3）、残りが吸収される。ただしこの釣り合いは全球平均での話で、緯度別に見ると太陽高度が高い低緯度では吸収が射出を上回って黒字、高緯度では射出が上回って赤字になる。この不均衡を解消するのが大気と海洋による低緯度から高緯度への熱輸送であり、中緯度の温帯低気圧やジェット気流、海流はその担い手である。\n\n【図解】緯度別の放射収支\n　緯度帯｜太陽放射の吸収｜放射収支\n　低緯度｜大きい｜黒字（余剰）\n　緯度約38度｜射出とほぼ等しい｜ほぼ均衡\n　高緯度｜小さい｜赤字（不足）\n　⇒ 不均衡は大気と海洋の南北熱輸送によって埋め合わされる\n　⚠ 低緯度を赤字、高緯度を黒字とするのは逆。また高緯度でも熱輸送は不可欠である。',
    difficulty: 'standard',
