    question: '温室効果のメカニズムに関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '温室効果ガス（水蒸気・二酸化炭素など）は、太陽から入射する短波放射（可視光）を強く吸収することで地表を暖める。', explanation: '誤り。温室効果ガスは主に地表から射出される長波放射（赤外放射）を強く吸収する性質を持ち、太陽からの短波放射（可視光）に対してはほぼ透明（吸収が弱い）である。' },
      { key: 'B', text: '温室効果ガスは地表から射出される長波放射（赤外放射）の一部を吸収し、その一部を再び地表方向へ放射し戻すことで、地表付近の気温を放射平衡のみの場合より高く保つ。', explanation: '正しい。温室効果ガス（水蒸気・二酸化炭素・メタンなど）は地表から射出される長波放射（赤外放射）を吸収し、大気自身も赤外放射を四方八方に再放射する。このうち地表方向へ戻る成分（下向き放射）が地表を追加的に暖め、温室効果ガスがない場合に比べて地表付近の気温を高く保つ。' },
      { key: 'C', text: '温室効果ガスの濃度が増加しても、地表付近の平衡気温には影響しない。', explanation: '誤り。温室効果ガスの濃度が増加すると、地表から射出される長波放射の吸収・再放射の効果が強まり、地表付近の平衡気温は上昇する方向に影響を受ける（地球温暖化の主要な要因の一つ）。' },
      { key: 'D', text: '温室効果は地球特有の現象であり、他の惑星の大気には見られない。', explanation: '誤り。温室効果は大気の組成に応じて他の惑星（例えば金星の非常に強い二酸化炭素による温室効果）にも見られる、一般的な放射のメカニズムである。' },
    ],
    correctKey: 'B',
    explanation: '温室効果は、大気中の水蒸気・二酸化炭素・メタン・一酸化二窒素・オゾンなどの温室効果気体が、地表から射出される長波（赤外）放射を吸収し、その一部を再び地表方向へ射出することで生じる。これにより地表が受け取るエネルギーが増え、温室効果がない場合の放射平衡温度である約−19 ℃に対し、実際の地球の平均地上気温は約15 ℃に保たれている。温室効果気体は可視域の太陽放射はほとんど吸収せず素通りさせる点が重要で、短波を吸収するわけでも長波を鏡のように反射するわけでもない。金星の高温も強い温室効果によるもので、地球特有の現象ではない。\n\n【図解】温室効果のしくみ\n　放射｜温室効果気体の作用｜結果\n　短波（太陽放射）｜ほとんど吸収せず透過｜地表を暖める\n　長波（地球放射）｜吸収して再放射｜一部が地表へ戻る\n　温室効果なし｜―｜平均約−19 ℃\n　温室効果あり｜―｜平均約15 ℃\n　⇒ 吸収と再放射であって、反射ではない点が本質である\n　⚠ 「短波放射を強く吸収して暖める」は誤り。吸収するのは地表からの長波放射。',
    difficulty: 'standard',
    examYear: '令和6年',
