    correctKey: 'B',
    explanation: '暖かい雨は、氷相を経ずに液体の水滴だけで雨滴が作られる降水過程で、衝突併合過程によって進む。雲の中には大きさの異なる水滴が存在し、大きい水滴ほど落下速度が速いため、落下しながら小さい水滴を捕捉して成長する。雲粒の半径は約10 μmだが、雨滴になるには約1000 μmまで成長する必要があり、体積では約100万倍に達する。凝結だけでは時間がかかりすぎるため、この併合過程が不可欠である。海塩粒子のような大きな凝結核が存在し、雲粒の大きさに幅がある海洋上や熱帯で効率よく働くが、日本の夏の背の低い雲でも起こりうる。\n\n【図解】暖かい雨の成長過程\n　段階｜半径のめやす｜おもな機構\n　雲凝結核｜約0.1 μm｜エアロゾル\n　雲粒｜約10 μm｜水蒸気の凝結\n　霧雨粒｜約100 μm｜衝突併合\n　雨滴｜約1000 μm｜衝突併合\n　⇒ 雲粒の大きさに幅があることが併合が進む条件である\n　⚠ 「暖かい雨も氷晶を経由する」は誤り。氷を介さない過程だからこの名がある。',
