    explanation: '雲凝結核は、水蒸気が凝結して雲粒になる際の足場となる大気中の微小粒子で、海塩粒子、土壌粒子、燃焼起源の硫酸塩などのエアロゾルがこれにあたる。核がまったくない清浄な空気では、均質核形成のために数百 %という現実にはあり得ない過飽和度が必要になるが、吸湿性の核があれば過飽和度わずか0.1〜1 %程度で雲粒が生成できる。核の数濃度は雲粒の大きさ分布を左右し、核が多すぎると雲粒が小さく多数になって併合が進みにくく、降水効率が下がる。氷晶核は氷の結晶構造に近い鉱物粒子などが働き、雲凝結核とは別の粒子である。\n\n【図解】雲凝結核の働き\n　条件｜必要な過飽和度｜雲粒の生成\n　核がない｜数100 %｜現実には起こらない\n　吸湿性の核がある｜0.1〜1 %程度｜容易に生成\n　核が非常に多い｜低い｜小粒で多数・降水しにくい\n　⇒ 核の数濃度が雲粒の大きさと降水効率を左右する\n　⚠ 雲凝結核と氷晶核は別物である。同じ粒子が常に両方を担うわけではない。',
