    explanation: '大気境界層では地表面の摩擦により風速が落ち、風速に比例するコリオリ力も弱まる。その結果、気圧傾度力とつり合いきれず、風は等圧線を横切って低圧側へ吹き込む成分をもつ。この横切る角度は摩擦が強いほど大きく、地表付近が最大で、陸上ではおよそ30〜45度、摩擦の小さい海上では10〜20度程度である。高度が上がるにつれ摩擦の影響が薄れて風速は増し、風向は時計回り（北半球）に変わりながら、境界層上端でほぼ等圧線に平行な地衡風に近づく。この構造をエクマン螺旋と呼び、低気圧中心への収束と上昇流、高気圧からの吹き出しを生む要因となる。\n\n【図解】摩擦による風のずれ\n　場所｜等圧線を横切る角度｜風速\n　陸上の地表付近｜約30〜45度｜最も弱い\n　海上の地表付近｜約10〜20度｜やや強い\n　境界層上端｜ほぼ0度｜地衡風に一致\n　⇒ 摩擦は風速を弱めるだけでなく、風向も低圧側へねじ曲げる\n　⚠ 「陸上のほうがねじれが小さい」は逆。摩擦が大きい陸上ほど角度は大きい。',
