    correctKey: 'B',
    explanation: 'オメガ方程式は準地衡風の渦度方程式と熱力学方程式を組み合わせて導かれる診断式で、鉛直流ωを二つの強制項から求める。第一項は渦度移流の鉛直方向の変化で、上層ほど正渦度移流が強まる場所では上昇流が誘起される。第二項は温度移流のラプラシアンで、暖気移流の極大域では上昇流、寒気移流の極大域では下降流となる。したがって上層トラフ前面の正渦度移流と下層の暖気移流が重なる領域が、最も上昇流が強く低気圧の発達と降水が集中しやすい場所となる。気温場の情報が不可欠であり、風の場だけでは診断できない。\n\n【図解】オメガ方程式の強制項\n　強制項｜条件｜鉛直流\n　渦度移流項｜上層で正渦度移流が増大｜上昇流\n　渦度移流項｜上層で負渦度移流が増大｜下降流\n　温度移流項｜下層で暖気移流｜上昇流\n　温度移流項｜下層で寒気移流｜下降流\n　⇒ 二つの強制が同じ向きに重なる領域で上昇流が最大となる\n　⚠ 「気温場の情報は不要」は誤り。温度移流項があるため気温場が必須である。',
