    question: '傾圧不安定が発達するための必要条件に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '傾圧不安定は、鉛直方向の風のシアー（すなわち水平温度傾度、温度風の存在）を必要とし、これが大きいほど不安定は強まりやすい。', explanation: '正しい。傾圧不安定は、鉛直方向の風のシアー（高度とともに地衡風が変化すること＝温度風の存在＝水平温度傾度の存在）を根本的なエネルギー源とする不安定であり、水平温度傾度が大きい（傾圧性が強い）ほど、一般に不安定はより強く発達しやすい。' },
      { key: 'B', text: '傾圧不安定は鉛直シアーがゼロ（順圧的）な大気で最も強く発達する。', explanation: '誤り。鉛直シアーがゼロ（順圧的）な大気では傾圧不安定のエネルギー源となる水平温度傾度が存在しないため、傾圧不安定は発達しない。この場合に問題となりうるのは順圧不安定である。' },
      { key: 'C', text: '傾圧不安定は水蒸気の存在を必須の条件とし、乾燥大気中では発達しない。', explanation: '誤り。傾圧不安定は基本的に乾燥大気の力学（南北温度差と鉛直シアー）だけでも発達しうる不安定であり、水蒸気（潜熱）の存在は発達を強化しうる要素ではあるが、必須条件ではない。' },
      { key: 'D', text: '傾圧不安定の発達には赤道での強いコリオリ力が必要である。', explanation: '誤り。コリオリ力は赤道でゼロとなるため、傾圧不安定（コリオリ力の緯度変化やコリオリ力そのものが関与する力学）は中緯度でより顕著に発達し、赤道付近で発達するものではない。' },
    ],
    correctKey: 'A',
    explanation: '傾圧不安定は、水平温度傾度が存在する大気、すなわち温度風の関係により地衡風が高度とともに変化する（鉛直シアーがある）大気で生じる不安定である。南北の温度差がもつ有効位置エネルギーが源で、暖気が北上しながら上昇し寒気が南下しながら下降する斜めの循環によってそれが運動エネルギーへ変換される。したがって鉛直シアーが大きいほど、また静的安定度が小さいほど発達しやすい。水蒸気の凝結潜熱は発達を助ける効果はあるが必須条件ではなく、乾燥大気でも傾圧不安定は成立する。またコリオリ力が働く中緯度が舞台であり、赤道では成立しない。\n\n【図解】傾圧不安定の条件\n　要素｜必要な状態｜理由\n　水平温度傾度｜大きい｜有効位置エネルギーの源\n　鉛直シアー｜大きい｜温度風として現れる\n　静的安定度｜小さいほど有利｜鉛直運動がしやすい\n　緯度｜中緯度｜コリオリ力が必要\n　⇒ 発達すると南北の温度差を減らす向きに熱を輸送する\n　⚠ 「順圧的な大気で最も発達」は誤り。鉛直シアーがなければ傾圧不安定は起きない。',
