    subjectName: '予報業務に関する一般知識',
    question: '順圧不安定に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '順圧不安定は南北の温度差（傾圧性）を主なエネルギー源とする不安定である。', explanation: '誤り。南北の温度差（傾圧性）を主なエネルギー源とするのは傾圧不安定である。順圧不安定は水平方向の風速の強いシアー（水平シアー）を主なエネルギー源とする、傾圧不安定とは異なる種類の不安定である。' },
      { key: 'B', text: '順圧不安定は主に水平方向の風速の強いシアー（相対渦度の水平分布に極大・極小があること）をエネルギー源とし、鉛直シアーがない（順圧的な）大気中でも発達しうる不安定である。', explanation: '正しい。順圧不安定は、水平方向に強い風速シアーが存在する流れ（例えばジェット気流の縁など）において、相対渦度の水平勾配の符号が変化する条件（順圧不安定の必要条件）を満たすときに発達する不安定であり、鉛直シアー（傾圧性）がなくても水平シアーだけで発達しうる点が傾圧不安定と異なる。' },
      { key: 'C', text: '順圧不安定は必ず傾圧不安定と同時にのみ発生し、単独では発生しない。', explanation: '誤り。順圧不安定は傾圧不安定とは独立した力学的な不安定機構であり、水平シアーの条件さえ満たせば単独でも発生しうる（現実の大気では両者が混在することも多い）。' },
      { key: 'D', text: '順圧不安定は台風の眼の形成にのみ関係する概念であり、中緯度の大気力学とは無関係である。', explanation: '誤り。順圧不安定は台風の眼の壁雲付近の渦の不安定（メソ渦の形成）だけでなく、中緯度のジェット気流の縁の波動の発達など、幅広い大気力学の場面で議論される一般的な概念である。' },
    ],
    correctKey: 'B',
    explanation: '順圧不安定は、水平方向の風速シアーが強く相対渦度の水平分布に極値をもつ流れで生じる不安定で、平均流の運動エネルギーが擾乱の運動エネルギーへ変換されることで発達する。理論的にはレイリーの必要条件として、流れの中に絶対渦度の南北傾度がゼロになる点が存在することが求められる。鉛直シアーすなわち傾圧性を必要としない点が傾圧不安定との決定的な違いで、順圧的な大気でも成立する。熱帯の偏東風波動や台風の眼の壁雲に現れる多角形の変形、渦の分裂などがその現れとされ、中緯度でもジェットの水平シアーに伴って生じうる。\n\n【図解】順圧不安定と傾圧不安定\n　項目｜順圧不安定｜傾圧不安定\n　エネルギー源｜平均流の運動エネルギー｜南北温度差の位置エネルギー\n　必要なシアー｜水平シアー｜鉛直シアー\n　温度傾度｜不要｜必須\n　代表例｜偏東風波動｜温帯低気圧\n　⇒ 順圧不安定は温度差がなくても水平シアーだけで成立する\n　⚠ 順圧不安定のエネルギー源を南北の温度差とするのは傾圧不安定との取り違え。',
