    choices: [
      { key: 'A', text: 'ストームトラックは赤道付近に形成される、台風の経路が集中する帯のことをいう。', explanation: '誤り。ストームトラックは中緯度の温帯低気圧（および移動性高気圧）の経路が統計的に集中する帯状の領域を指す用語であり、台風の経路帯を指すものではない。' },
      { key: 'B', text: 'ストームトラックは傾圧帯（南北温度差の大きい帯）から離れた、傾圧性のほとんどない領域に形成される。', explanation: '誤り。ストームトラックは傾圧不安定によって発達する温帯低気圧が繰り返し通過する経路であるため、傾圧帯（南北温度差が大きくジェット気流が卓越する帯）とおおむね一致する位置に形成される。' },
      { key: 'C', text: 'ストームトラックは中緯度の傾圧帯（ジェット気流帯）に沿って形成され、傾圧不安定によって発達した温帯低気圧が繰り返し通過することで統計的に低気圧の経路が集中する帯として現れる。', explanation: '正しい。ストームトラックは、中緯度の傾圧帯（強い水平温度傾度とジェット気流が存在する帯）に沿って、傾圧不安定により次々と発達する温帯低気圧の経路が統計的に集中することで形成される帯状の領域である。北太平洋や北大西洋にそれぞれ明瞭なストームトラックが存在する。' },
      { key: 'D', text: 'ストームトラックの位置は季節や年によらず常に同じ緯度に固定されている。', explanation: '誤り。ストームトラックの位置は季節（ジェット気流や傾圧帯の季節的な南北移動）や、エルニーニョ・ラニーニャなどの大規模な大気海洋変動の影響を受けて、年々変動する。' },
    ],
    correctKey: 'C',
    explanation: 'ストームトラックは、温帯低気圧の経路や擾乱活動が統計的に集中する帯状の領域で、中緯度の傾圧帯すなわちジェット気流に沿って形成される。傾圧不安定によって次々に低気圧が発生・発達しながら東進するため、北太平洋では日本の東海上から北太平洋中部へ、北大西洋では北米東岸から北欧へ延びる帯として現れる。位置と強さは季節によって変わり、南北温度傾度が大きい冬に強まり南下する。またエルニーニョや北極振動などの年々変動によっても南北にずれ、地域の天候の平年差を生む。傾圧性のない領域には形成されない。\n\n【図解】ストームトラックの特徴\n　項目｜内容｜補足\n　位置｜中緯度の傾圧帯に沿う｜ジェット気流と対応\n　成因｜傾圧不安定による低気圧の連続発生｜統計的な集中帯\n　季節変化｜冬に強く南下｜温度傾度に対応\n　年々変動｜エルニーニョや北極振動｜南北にずれる\n　⇒ ストームトラックの位置ずれが地域の天候の平年差を生む\n　⚠ 「傾圧性のない領域に形成される」「位置は常に固定」はいずれも誤り。',
