    explanation: '成層圏突然昇温は、冬の極域成層圏で気温が数日のうちに数十 K も上昇する現象である。対流圏で励起されたプラネタリー波（超長波）が成層圏へ上方伝播し、そこで砕けて西風の平均流にブレーキをかけることで、極を取り巻く西風の極渦が弱まったり、変位・分裂したりする。それに伴う下降流の断熱昇温で極域の気温が急上昇する。西風が東風に反転するものを大昇温（メジャー）と呼ぶ。この影響は数週間かけて対流圏へ下方伝播し、北極振動を負の位相へ導いて中緯度に寒波をもたらすことがあるため、季節予報上も重視される。毎年決まって起こるものではない。\n\n【図解】成層圏突然昇温の流れ\n　段階｜起きること｜結果\n　上方伝播｜プラネタリー波が成層圏へ｜西風を減速\n　極渦の変化｜弱化・変位・分裂｜下降流の発生\n　断熱昇温｜極域成層圏の気温が急上昇｜数日で数10 K\n　下方影響｜北極振動が負の位相へ｜中緯度に寒波\n　⇒ 成層圏の変動が数週間遅れて対流圏の天候に影響しうる\n　⚠ 「対流圏の天候に影響しない」「毎年同じ時期に必ず起こる」はいずれも誤り。',
