    choices: [
      { key: 'A', text: '台風の急速強化は、海面水温が低く鉛直シアー（上層と下層の風速差）が強い環境で起こりやすい。', explanation: '誤り。逆である。急速強化は一般に、海面水温が高く（水蒸気・潜熱の供給が豊富）、かつ鉛直シアーが弱い（対流構造が乱されにくい）環境で起こりやすい。' },
      { key: 'B', text: '台風の急速強化は、周囲の鉛直シアーが弱く、暖かい海面水温（十分な深さの暖水層）が持続し、上層の発散（アウトフロー）が良好な環境で起こりやすい。', explanation: '正しい。台風の急速強化（一般に24時間で中心付近の最大風速が大きく増加する現象）は、周囲の鉛直シアーが弱く対流構造が乱されにくいこと、海面水温が高く十分な深さまで暖水層が存在すること（台風自身がもたらす下層冷水の湧昇の影響を受けにくいこと）、上層の発散（アウトフロー）が良好で中心付近の質量収支が保たれることなど、複数の好条件が重なった場合に起こりやすい。' },
      { key: 'C', text: '台風の急速強化は上層の発散（アウトフロー）が悪い（弱い）環境ほど起こりやすい。', explanation: '誤り。上層の発散（アウトフロー）が良好であるほど、台風の眼の壁雲付近での質量の吹き出しがスムーズになり、下層からの空気の流入・上昇流が持続しやすくなるため、急速強化に有利に働く。発散が悪い（弱い）環境は不利である。' },
      { key: 'D', text: '台風の急速強化は台風の大きさ（強風域の半径）のみによって一意に決まり、環境場の影響は受けない。', explanation: '誤り。急速強化は海面水温・鉛直シアー・上層の発散状況など複数の環境場の要因が複合的に影響する現象であり、台風の大きさのみで一意に決まるものではない。' },
    ],
    correctKey: 'B',
    explanation: '台風の急速強化（RI）は、24時間で中心気圧が大きく下がる、あるいは最大風速が15 m/s 程度以上増大する現象で、防災上とくに警戒を要する。起こりやすいのは、鉛直シアーが弱く対流の熱と水蒸気が中心付近に集中できること、海面水温が高くしかも暖水層が厚いため強風でかき混ぜても冷えにくいこと、上層に良好なアウトフローがあって発散が確保されること、周囲の中層が湿っていて乾燥空気の侵入が少ないことなどの条件がそろう場合である。逆に強い鉛直シアーは対流を傾けて暖気核を崩し、低い海面水温は水蒸気供給を絶って発達を妨げる。\n\n【図解】急速強化に有利な環境\n　条件｜有利な状態｜不利な状態\n　鉛直シアー｜弱い｜強い\n　海面水温と暖水層｜高く厚い｜低く薄い\n　上層のアウトフロー｜良好｜弱い\n　中層の湿り｜湿潤｜乾燥空気の侵入\n　⇒ 対流の熱を中心付近に集中させられるかが鍵となる\n　⚠ 「上層発散が弱いほど急速強化しやすい」は逆。良好なアウトフローが必要である。',
