    question: '台風の眼の形成に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '台風の眼は、中心付近の強い低気圧性回転による遠心力とコリオリ力・気圧傾度力のバランス（傾度風平衡に近い状態）の中で、中心付近に緩やかな下降流域が形成されることで生じるとされる。', explanation: '正しい。台風が発達し中心付近の回転が非常に強くなると、力学的なバランス（気圧傾度力・コリオリ力・遠心力）の中で中心付近にわずかな下降流域が形成されやすくなり、これが雲のない（または少ない）眼を作り出すと考えられている。眼の壁雲（アイウォール）で強い上昇流が生じる一方、その内側の眼では相対的な下降流が卓越する。' },
      { key: 'B', text: '台風の眼は台風の勢力にかかわらず、必ず直径50 km以上の大きさになる。', explanation: '誤り。台風の眼の直径は台風の発達段階や個々の台風によって様々であり、数km程度の小さな眼から100km近い大きな眼まで幅がある。必ず50km以上になるわけではない。' },
      { key: 'C', text: '台風の眼は上昇流が非常に強い領域であり、最も激しい雷雲が発達する。', explanation: '誤り。上昇流が非常に強く激しい対流雲（積乱雲）が発達するのは眼を取り囲む眼の壁雲（アイウォール）であり、眼そのものはむしろ下降流が卓越し、比較的雲の少ない静穏な領域である。' },
      { key: 'D', text: '台風の眼は熱帯低気圧の段階から常に明瞭に観測される構造であり、発達段階による変化はない。', explanation: '誤り。眼は台風がある程度発達しないと明瞭には現れず、発達の初期段階（熱帯低気圧の段階）では明瞭な眼が見られないことが多い。台風が発達し勢力を増すにつれて眼が明瞭になっていくのが一般的な傾向である。' },
    ],
    correctKey: 'A',
    explanation: '台風の眼は、中心付近で気圧傾度力・コリオリ力・遠心力がつり合う旋衡風ないし傾度風平衡に近い状態が成り立ち、その内側で空気が緩やかに下降することで生じる雲のない領域である。下降流に伴う断熱昇温が中心付近の暖気核を強めるため、眼の明瞭さは台風の強さの指標にもなる。直径は20〜200 km程度と幅があり、発達した強い台風ほど小さく円形で明瞭になる傾向がある。熱帯低気圧の段階では眼は不明瞭で、発達に伴って現れる。強い台風では眼の壁雲が二重になり、外側の壁雲が収縮して内側が消える眼の壁雲交換が起こり、一時的に勢力が弱まることもある。\n\n【図解】眼と眼の壁雲\n　部位｜鉛直流｜特徴\n　眼｜緩やかな下降流｜雲がなく風も弱い\n　眼の壁雲｜強い上昇流｜最大風速と最強の降水\n　眼の明瞭さ｜―｜発達した台風ほど明瞭\n　⇒ 眼の下降流による断熱昇温が暖気核を強める\n　⚠ 「眼で上昇流が強く雷雲が発達」は誤り。上昇流が強いのは眼の壁雲である。',
