    correctKey: 'C',
    explanation: '台風の強風が海面に働くと、エクマン輸送により表層の海水が中心から外向きに運ばれて発散が生じ、それを補うように下層の冷たい海水が湧き上がる。また強いシアーによる鉛直混合も加わり、台風の通過後には進路上の海面水温が数 ℃低下した冷水域（コールドウェイク）が残る。海面水温の低下は水蒸気供給を減らすため、台風自身の発達を抑える負のフィードバックとして働き、同じ経路をたどる後続の台風の勢力も弱める。効果は移動速度が遅いほど大きく、また暖水層が薄い海域ほど顕著になる。移動が速い台風はこの影響を受けにくい。\n\n【図解】台風と海洋の相互作用\n　過程｜起きること｜台風への影響\n　エクマン輸送｜表層で発散｜冷水の湧昇\n　鉛直混合｜下層の冷水と混ざる｜海面水温の低下\n　移動が遅い｜冷却が進む｜勢力が抑えられる\n　移動が速い｜冷却が小さい｜影響を受けにくい\n　⇒ 冷水湧昇は台風の発達を抑える負のフィードバックである\n　⚠ 「移動が速いほど冷水湧昇の影響を強く受ける」は逆。遅いほど影響が大きい。',
