    correctKey: 'C',
    explanation: '大気の川は、下層ジェットなどに沿って形成される幅数百 km、長さ数千 kmに及ぶ水蒸気輸送が集中した帯状の領域で、中緯度の水蒸気輸送の大部分を担う。可降水量や水蒸気フラックスが周囲より格段に大きく、水蒸気画像や解析図では明るい湿潤域として現れる。この流れが山地の斜面や停滞前線にぶつかって強制的に持ち上げられると、大量の水蒸気が凝結して長時間の大雨をもたらす。米国西岸の豪雨や、日本の梅雨期・秋雨期の集中豪雨、線状降水帯の背景場としても重視され、近年は防災上のキーワードとして定着している。\n\n【図解】大気の川の特徴\n　項目｜内容｜補足\n　形状｜幅数100 km・長さ数1000 km｜帯状\n　高度｜下層（850 hPa 付近が中心）｜下層ジェットに沿う\n　水蒸気画像｜明るい湿潤域｜乾燥域ではない\n　災害｜地形や前線での強制上昇｜集中豪雨\n　⇒ 中緯度の水蒸気輸送の大半をこの狭い帯が担っている\n　⚠ 「大気全体に一様に分布する水蒸気層」「常に乾燥域として写る」はいずれも誤り。',
