    subjectName: '予報業務に関する一般知識',
    question: '日本海寒帯気団収束帯（JPCZ）に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: 'JPCZは、冬型の気圧配置の際、大陸から吹き出す寒気が朝鮮半島の山地（長白山脈など）で二手に分かれ、日本海上で再び合流して収束帯を形成し、活発な対流雲（雪雲）の帯を作り出す現象である。', explanation: '正しい。JPCZ（日本海寒帯気団収束帯）は、冬型の気圧配置のもとで大陸から吹き出す寒気が朝鮮半島北部の山地の影響で二手に分かれて日本海へ流れ出し、日本海上で再び合流（収束）することで、活発な対流雲（筋状の雪雲）の帯を形成する現象である。この収束帯が北陸地方などに向かうと、局地的な大雪をもたらすことがある。' },
      { key: 'B', text: 'JPCZは夏季にのみ発生する現象であり、冬季には見られない。', explanation: '誤り。JPCZは冬型の気圧配置（大陸からの季節風）に伴って発生する冬季特有の現象であり、夏季には見られない。' },
      { key: 'C', text: 'JPCZは太平洋側の地域にのみ大雪をもたらす現象である。', explanation: '誤り。JPCZに伴う収束帯（雪雲の筋）は主に日本海側の地域（北陸地方など）に局地的な大雪をもたらす現象であり、太平洋側への直接的な影響は限定的である。' },
      { key: 'D', text: 'JPCZは移動性高気圧の接近時にのみ形成される現象である。', explanation: '誤り。JPCZは移動性高気圧ではなく、冬型の気圧配置（西高東低、大陸のシベリア高気圧からの季節風）のもとで形成される現象である。' },
    ],
    correctKey: 'A',
    explanation: '日本海寒帯気団収束帯（JPCZ）は、冬型の気圧配置のもとで大陸から吹き出す寒気が、朝鮮半島北部の長白山脈などの高い山地を迂回して二手に分かれ、日本海上で再び合流することによってできる収束帯である。収束による強い上昇流に加え、暖かい対馬海流の上を渡る際の気団変質で下層に熱と水蒸気が大量に供給されるため、帯状の発達した対流雲（雪雲）が形成される。この雲バンドが北陸や山陰などの日本海側に流入・停滞すると、局地的に短時間で降雪量が急増する大雪となる。太平洋側では山脈を越える際に水蒸気を失い、からっ風となって晴天になる。\n\n【図解】JPCZ の成り立ち\n　段階｜場所｜起きること\n　分流｜朝鮮半島北部の山地｜寒気が二手に分かれる\n　収束｜日本海中部｜再合流して収束帯を形成\n　気団変質｜対馬海流上｜熱と水蒸気の供給\n　降雪｜日本海側｜帯状の雪雲による大雪\n　⇒ 収束と気団変質が重なるため、局地的に極端な降雪となる\n　⚠ JPCZ は冬型の気圧配置で生じ、大雪をもたらすのは日本海側である。',
