    question: '線状降水帯の形成メカニズム（バックビルディング型）に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: 'バックビルディング型の線状降水帯は、一つの積乱雲が同じ場所に長時間停滞することで形成される。', explanation: '誤り。バックビルディング型は単独の積乱雲の停滞ではなく、下層の湿った暖かい空気の流入によって同じ場所（風上側）で次々と新しい積乱雲が発生し、それらが上空の風（一般風）に流されて下流側へ移動していくことで、結果として帯状の降水域が同じ地域に長時間持続する現象である。' },
      { key: 'B', text: 'バックビルディング型の線状降水帯は、下層の暖湿な気流の収束などにより、同じ場所（風上端）で次々と新たな積乱雲が世代交代しながら発生し、それらが上空の風に流されて下流側へ移動することで、結果的に線状の降水域が同じ地域に長時間持続する現象である。', explanation: '正しい。バックビルディング型は、下層ジェットなどによる暖湿な空気の持続的な流入と収束によって、線状降水帯の風上端で次々と新しい積乱雲（セル）が発生し（世代交代）、発生した各セルは上空の風に流されて下流側（風下側）へ移動しながら発達・衰弱していく。この結果、個々の積乱雲は移動しても、新しいセルが次々と同じ場所で発生し続けるため、線状の降水域全体としては同じ地域に長時間とどまり、集中豪雨をもたらす。' },
      { key: 'C', text: 'バックビルディング型の線状降水帯は、上空の風が非常に弱い（無風に近い）場合にのみ形成される。', explanation: '誤り。バックビルディング型の形成には、下層の暖湿気流の持続的な流入・収束に加え、新しく発生した積雲群を下流側へ移動させる上空の風（一般風）の存在も重要な要素であり、無風に近い状態でのみ形成されるわけではない。' },
      { key: 'D', text: 'バックビルディング型の線状降水帯は数分程度で発生から消滅までを終える、短寿命の現象である。', explanation: '誤り。バックビルディング型の線状降水帯は、新しい積乱雲が次々と世代交代しながら発生し続けることで、数時間程度にわたって同じ地域に強い降水をもたらし続けることがある、比較的長寿命な現象である。' },
    ],
    correctKey: 'B',
    explanation: 'バックビルディング型は線状降水帯を作る代表的な組織化の様式で、下層の暖湿気流の収束や地形による強制上昇によって、線状降水帯の風上端で新しい積乱雲が次々と発生することが特徴である。個々の積乱雲の寿命は1時間程度だが、発生した雲は上空の風で下流側へ流されながら成熟・衰弱し、その間に風上端でまた新しい雲が生まれる。この世代交代が続くことで、降水域全体は同じ場所に長時間とどまり、数時間にわたって強い雨が同一地域に降り続ける。発生の条件としては、大量の水蒸気流入、条件付き不安定、持続する下層収束、上空の適度な風が挙げられる。\n\n【図解】線状降水帯が持続する仕組み\n　位置｜積乱雲の状態｜役割\n　風上端｜新しい雲が発生｜世代交代の起点\n　中間｜成熟期の雲｜最も強い降水\n　風下端｜衰弱期の雲｜降水が弱まる\n　全体｜線状に並び停滞｜同じ地域に長時間の強雨\n　⇒ 個々の雲は移動しても、降水帯全体はほぼ動かない点が危険である\n　⚠ 「一つの積乱雲が停滞して起こる」は誤り。次々に発生する世代交代が本質。',
