    correctKey: 'A',
    explanation: 'ダウンバーストは、積乱雲の中で降水粒子の蒸発や融解による冷却と、降水の引きずり効果によって生じた強い下降流が地表に叩きつけられ、水平方向に放射状に吹き出す現象である。突風の吹き出しは中心から外向きに広がる発散性の風系で、竜巻のような収束性の渦とは風の分布が明確に異なり、被害の跡が放射状に広がる点で区別できる。影響範囲が水平規模4 km未満のものをマイクロバースト、4 km以上をマクロバーストという。離着陸中の航空機が急激な向かい風から追い風へ変化する場面に遭遇すると揚力を失い墜落の危険があるため、空港ではドップラーレーダーや低層風のシアー検知装置で監視されている。\n\n【図解】ダウンバーストと竜巻\n　項目｜ダウンバースト｜竜巻\n　風の分布｜発散性（外向き）｜収束性（渦）\n　被害の跡｜放射状に倒れる｜巻き込むように倒れる\n　規模の区分｜4 km未満はマイクロバースト｜―\n　⇒ 航空機の離着陸時にとって最も危険な低層のウィンドシアーである\n　⚠ マイクロバーストはダウンバーストの小規模なほう。大規模なものとするのは誤り。',
