    choices: [
      { key: 'A', text: 'スーパーセル型の竜巻は、上空の風のシアーとは無関係に、地表付近の局地的な加熱のみによって発生する。', explanation: '誤り。スーパーセル型の竜巻の発生には、上空の強い風のシアー（メソサイクロンの形成に関わる）が本質的に重要な役割を果たしており、地表付近の局地的な加熱のみで説明される現象ではない。' },
      { key: 'B', text: 'スーパーセル型の竜巻は、スーパーセル内部の持続的な回転（メソサイクロン）に伴う渦が、下降流（リアフランクダウンドラフトなど）の作用を受けながら地表付近で収縮・強化されることで発生すると考えられている。', explanation: '正しい。スーパーセル型の竜巻は、スーパーセル内部に既に存在する中規模の回転（メソサイクロン）を起点として、その渦がリアフランクダウンドラフト（RFD：後面下降流）などの下降流の作用を受けながら地表付近まで到達・収縮し、角運動量保存の効果もあって回転が強化されることで、地表に達する強い渦（竜巻）として発生すると考えられている。' },
      { key: 'C', text: 'スーパーセル型の竜巻はメソサイクロンとは無関係に、独立して発生する現象である。', explanation: '誤り。スーパーセル型の竜巻の発生は、スーパーセル内部のメソサイクロン（持続的な中規模の回転）と密接に関連しており、無関係ではない。メソサイクロンを伴わない単一セルの積乱雲でも稀に弱い渦（非スーパーセル竜巻）が発生することはあるが、これはスーパーセル型とは異なる機構による。' },
      { key: 'D', text: 'スーパーセル型の竜巻は海上でのみ発生し、陸上では発生しない。', explanation: '誤り。竜巻は陸上・海上のいずれでも発生しうる現象であり、海上で発生し水面上を移動するものは特に「水上竜巻」と呼ばれることがあるが、スーパーセル型の竜巻は陸上でも発生する。' },
    ],
    correctKey: 'B',
    explanation: 'スーパーセル型の竜巻は、まず環境の鉛直シアーがもつ水平渦度が上昇流によって立ち上げられ、中層に回転する上昇流であるメソサイクロンが形成されることから始まる。次に、後面下降流（リアフランクダウンドラフト）がもたらす冷気外出流と、降水による下降流の縁で生じる水平渦度が地表付近で立ち上げられ、渦が地表に接する低層メソサイクロンが作られる。この渦が上昇流に引き伸ばされて渦度が集中（ストレッチング）することで、細く強烈な竜巻へと発達する。したがって竜巻はメソサイクロンと無関係ではなく、上空の回転と地表付近の渦の結合が鍵である。海上では水上竜巻となるが、陸上でも当然発生する。\n\n【図解】スーパーセル型竜巻の発生手順\n　段階｜起きること｜働く機構\n　第1段階｜水平渦度が立ち上がる｜鉛直シアーと上昇流\n　第2段階｜メソサイクロンの形成｜中層で回転が持続\n　第3段階｜低層の渦の形成｜後面下降流の関与\n　第4段階｜渦の収縮と強化｜上昇流によるストレッチング\n　⇒ 渦が引き伸ばされて渦度が集中することで竜巻が強まる\n　⚠ 「メソサイクロンと無関係に発生」「上空のシアーと無関係」はいずれも誤り。',
