    explanation: '特別警報は2013年8月に運用が始まった制度で、警報の発表基準をはるかに超える現象、具体的には府県程度の広がりで数十年に一度しか発生しないような、重大な災害の危険性が著しく高まっている場合に発表される。対象は大雨・暴風・高潮・波浪・暴風雪・大雪と、噴火・地震（緊急地震速報）・津波である。基準となる数値は地域ごとの気候や災害特性を踏まえて個別に設定されており、全国一律ではない。発表権限は気象業務法に基づき気象庁にあり、市町村長にはない。発表された時点ですでに災害が発生している可能性が高く、直ちに命を守る行動が求められる。\n\n【図解】警報と特別警報\n　区分｜想定される現象の程度｜求められる行動\n　注意報｜災害が起こるおそれ｜今後の情報に注意\n　警報｜重大な災害のおそれ｜安全な場所へ避難\n　特別警報｜数10年に一度の重大な災害｜直ちに命を守る行動\n　発表権限｜いずれも気象庁｜市町村長ではない\n　⇒ 特別警報が出た時点ですでに災害が発生している可能性が高い\n　⚠ 「数年に一度」「全国一律の基準」「市町村長が発表」はいずれも誤り。',
