    choices: [
      { key: 'A', text: '温室効果ガスの中で温室効果への寄与が最大なのは二酸化炭素であり、水蒸気による寄与は無視できるほど小さい。', explanation: '誤り。自然起源の温室効果ガスとして最大の寄与をしているのは水蒸気であるとされる。二酸化炭素は人為起源の温室効果ガスの中では影響が大きいが、自然の温室効果全体で見ると水蒸気の寄与が最大とされる。' },
      { key: 'B', text: '大気の主成分である窒素（N2）や酸素（O2）は代表的な温室効果ガスである。', explanation: '誤り。窒素や酸素は分子の構造上、地表からの赤外放射をほとんど吸収しないため、代表的な温室効果ガスには分類されない。温室効果ガスとして重要なのは水蒸気・二酸化炭素・メタン・一酸化二窒素・フロン類などである。' },
      { key: 'C', text: 'メタン（CH4）は温室効果を持たない気体である。', explanation: '誤り。メタンは赤外放射を吸収する性質を持つ代表的な温室効果ガスの一つであり、単位質量あたりの温室効果は二酸化炭素より大きいとされる。' },
      { key: 'D', text: '水蒸気は自然起源の温室効果ガスの中で最大の寄与をしているとされ、これに人為起源の二酸化炭素・メタン・一酸化二窒素・フロン類などが加わることで、全体としての温室効果が強化される。', explanation: '正しい。水蒸気は自然界に豊富に存在し、自然の温室効果への寄与が最大とされる温室効果ガスである。これに加えて、人間活動によって排出される二酸化炭素・メタン・一酸化二窒素・フロン類などの温室効果ガスが大気中に蓄積することで、全体としての温室効果が強化され、地球温暖化の要因となっている。' },
    ],
    correctKey: 'D',
    explanation: '温室効果をもつのは、赤外線を吸収・射出できる三原子以上の分子や異種二原子分子であり、水蒸気、二酸化炭素、メタン、一酸化二窒素、オゾン、フロン類などが該当する。対称な二原子分子である窒素と酸素は大気の約99 %を占めるが、赤外線をほとんど吸収しないため温室効果ガスではない。自然の温室効果への寄与が最大なのは水蒸気で、雲の効果も含めるとおよそ半分以上を占め、二酸化炭素は約2割程度とされる。ただし水蒸気の量は気温に従って決まる従属的な変数なので、人為的に増える二酸化炭素などが引き金となって気温が上がり、それが水蒸気を増やして温暖化を増幅する。\n\n【図解】主な温室効果ガス\n　気体｜おもな起源｜特徴\n　水蒸気｜自然起源｜寄与が最大・気温に従属\n　二酸化炭素｜化石燃料の燃焼など｜人為的増加の主役\n　メタン｜水田・家畜・湿地｜単位量あたりの効果が大きい\n　窒素・酸素｜大気の主成分｜温室効果はもたない\n　⇒ 水蒸気は増幅役、二酸化炭素は引き金役という役割分担で理解する\n　⚠ 窒素や酸素を温室効果ガスとするのは誤り。対称二原子分子は赤外線を吸収しない。',
