    explanation: '大気の窓とは、地表から射出される赤外放射のうち、水蒸気や二酸化炭素による吸収帯の谷間にあたり、大気をよく透過して宇宙へ抜けていく波長帯のことで、おおむね8〜12 μmを指す。地球放射のピークがこの付近にあるため、地球はこの窓を通して効率よく熱を宇宙へ捨てている。気象衛星の赤外画像はこの波長帯を利用しており、雲がなければ地表面や海面の温度を、雲があればその雲頂の温度を測定できる。ただし雲は赤外に対してほぼ不透明なので、雲を透過して地表を見ることはできない。なおこの窓の中にはオゾンの9.6 μm吸収帯があり、フロン類もこの帯域で吸収するため温室効果が強い。\n\n【図解】大気の窓の性質\n　波長帯｜大気の透過｜衛星観測での用途\n　約6.7 μm｜水蒸気が強く吸収｜水蒸気画像\n　約8〜12 μm｜よく透過（大気の窓）｜赤外画像・海面水温\n　約15 μm｜二酸化炭素が強く吸収｜気温の鉛直分布\n　⇒ 地球はこの窓を通して熱を宇宙へ効率よく捨てている\n　⚠ 「雲を透過して地表を直接観測できる」は誤り。雲は赤外に対してほぼ不透明である。',
